public class MySQLDatabase {
    private String connectionString;
    private boolean isConnected;

    public MySQLDatabase(String connectionString) {
        this.connectionString = connectionString;
        this.isConnected = false;
    }

    public void connect() {
        if (!isConnected) {
            System.out.println("Connecting to MySQL with: " + connectionString);
            isConnected = true;
        }
    }

    public void disconnect() {
        if (isConnected) {
            System.out.println("Disconnecting from MySQL");
            isConnected = false;
        }
    }

    public String getUserEmail(int userId) {
        if (!isConnected) {
            throw new RuntimeException("Database not connected");
        }
        return "user" + userId + "@company.com";
    }

    public boolean validateUser(int userId) {
        if (!isConnected) {
            throw new RuntimeException("Database not connected");
        }
        return userId > 0 && userId < 10000;
    }
}

public class EmailService {
    private MySQLDatabase database;
    private String smtpServer;

    public EmailService(String smtpServer) {
        this.smtpServer = smtpServer;
        this.database = new MySQLDatabase("jdbc:mysql://localhost:3306/users");
    }

    public void sendEmail(int userId, String subject, String message) {
        database.connect();

        if (!database.validateUser(userId)) {
            System.out.println("Invalid user ID: " + userId);
            return;
        }

        String email = database.getUserEmail(userId);
        System.out.println("Using SMTP server: " + smtpServer);
        System.out.println("Sending email to " + email);
        System.out.println("Subject: " + subject);
        System.out.println("Message: " + message);

        database.disconnect();
    }

    public void sendBulkEmails(int[] userIds, String subject, String message) {
        database.connect();

        for (int userId : userIds) {
            if (database.validateUser(userId)) {
                String email = database.getUserEmail(userId);
                System.out.println("Bulk email sent to: " + email);
            }
        }

        database.disconnect();
    }
}
